{"content":"import csv

def verify():
    stops = set()
    with open('outputs/t05_clean_stops.csv', mode='r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            stops.add(row['stop_id'])

    results_ids = []
    with open('outputs/t09_poi_nearest_stop.csv', mode='r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            results_ids.append(row['nearest_stop_id'])

    for sid in results_ids:
        if sid not in stops:
            print(f"Stop ID {sid} not found in t05_clean_stops.csv")
            return False
    print("All Stop IDs found.")
    return True

verify()
